for (const kind of ['ma', 'bb'] as IndicatorKind[]) test(`all ${kind} rolling points match independent Python values within rounding precision`, () => {
  const lines = lineIndicator(aggregate(scored, '1h'), kind);
  assert.equal(lines.length, rollingBaselines[kind].length);
  lines.forEach((line, i) => {
    assert.equal(line.data.length, rollingBaselines[kind][i].length);
    line.data.forEach((point, j) => assert.ok(Math.abs(point.value - rollingBaselines[kind][i][j]) <= 0.00010000001, `${kind} series ${i} point ${j}: ${point.value} vs ${rollingBaselines[kind][i][j]}`));
  });
});

for (const kind of Object.keys(expectedIndicators) as IndicatorKind[]) test(`all ${kind} indicator points reproduce independent Python defaults`, () => {
  const lines = lineIndicator(aggregate(scored, '1h'), kind);
  const canonical = lines.map(line => line.data.map(point => [point.time, point.value.toFixed(4)]));
  assert.equal(hash(canonical), expectedIndicators[kind]);
});

test('all 1,497 public group indices reproduce the independent Python result', () => {
  assert.equal(scored.length, 1497);
  assert.equal(scored.at(-1)?.relationship_index, 83.4186);
  assert.equal(hash(scored.map(row => row.relationship_index.toFixed(4))), expectedIndex);
  assert.equal(new Set(scored.filter(row => row.sender !== 'System').map(row => row.sender)).size, 5);
});

for (const timeframe of TIMEFRAMES) test(`every ${timeframe.id} candle reproduces Python OHLC, UTC time and counts`, () => {
  const candles = aggregate(scored, timeframe.id);
  const canonical = candles.map(c => [c.time, ...[c.open, c.high, c.low, c.close].map(v => v.toFixed(4)), c.message_count]);
  assert.equal(hash(canonical), expectedCandles[timeframe.id]);
  assert.equal(candles.reduce((count, c) => count + c.message_count, 0), 1497);
  for (const candle of candles) {
    assert.ok(candle.low <= candle.open && candle.low <= candle.close);
    assert.ok(candle.high >= candle.open && candle.high >= candle.close);
    assert.equal(candle.events.length, candle.message_count);
    assert.ok(candle.volume > 0);
  }
});

test('CSV supports BOM, quoted commas, escaped quotes, multiline text and stable equal timestamps', () => {
  const messages = parseChat('\uFEFFtimestamp,sender,message\r\n2026-11-18 09:00:00,B,"quoted, \"\"yes\"\"\nnext line"\r\n2026-11-17 09:00:00,A,first\r\n2026-11-18 09:00:00,C,last\r\n', 'chat.csv');
  assert.deepEqual(messages.map(m => m.sender), ['A', 'B', 'C']);
  assert.deepEqual(messages.map(m => m.id), [1, 2, 3]);
  assert.equal(messages[1].message, 'quoted, "yes"\nnext line');
  assert.equal(messages[1].timestamp, '2026-11-18T09:00:00+08:00');
});

test('JSON wrappers, aliases, epoch milliseconds, JSONL and TXT preserve actual timestamps', () => {
  const timestamp = Date.parse('2026-11-18T01:00:00Z');
  const raw = [{ ts: timestamp, from: 'A', content: 'A' }, { time: '2026-11-18T01:00:00Z', user: 'B', text: 'B' }];
  const messages = parseChat(JSON.stringify({ data: raw }), 'chat.json');
  const lines = parseChat(raw.map(r => JSON.stringify(r)).join('\n'), 'chat.jsonl');
  assert.deepEqual(messages, lines);
  assert.equal(messages[0].timestamp, '2026-11-18T09:00:00+08:00');
  assert.deepEqual(parseChat('2026-11-18 09:00:00 A: A', 'chat.txt'), [messages[0]]);
  assert.deepEqual(parseChat(JSON.stringify(raw[0]), 'chat.json'), [messages[0]]);
});

test('malformed files fail explicitly instead of silently dropping rows or fabricating dates', () => {
  assert.throws(() => parseChat('timestamp,sender,message\n2026-11-18,A,"unclosed', 'bad.csv'), /引号/);
  assert.throws(() => parseChat('timestamp,sender,message\n2026-11-18,A,one,extra', 'bad.csv'), /列数/);
  assert.throws(() => parseChat('[{"sender":"A","message":"missing time"}]', 'bad.json'), /时间/);
  assert.throws(() => parseChat('[{"timestamp":"2026-02-30","sender":"A","message":"x"}]', 'bad.json'), /日期/);
  assert.throws(() => parseChat('[{"timestamp":"2026-11-18T25:00:00","sender":"A","message":"x"}]', 'bad.json'), /时分秒/);
  assert.throws(() => parseChat('{"conversations":[{"role":"user","content":"hello"}]}', 'bad.json'), /时间戳/);
  assert.throws(() => parseChat('not a timestamp Alice: hello', 'bad.txt'), /第 1 行/);
  assert.throws(() => parseChat('{}\n{bad}', 'bad.jsonl'), /第 2 行/);
});

test('numerical recurrence starts at 50, decays by actual elapsed hours and is not clamped', () => {
  const messages = Array.from({ length: 6 }, (_, i): Message => ({ id: i + 1, timestamp: '2026-11-18T00:00:00+08:00', sender: 'A', message: 'x' }));
  const scores = messages.map((m): Score => ({ id: m.id, delta_vs_prior: 15, delta_vs_atmosphere: 15, primary_dim: 'investment', rationale: '' }));
  assert.equal(scoreMessages(messages, scores).at(-1)?.relationship_index, 140);
  messages[5].timestamp = '2026-11-21T00:00:00+08:00';
  scores[5].delta_vs_prior = scores[5].delta_vs_atmosphere = 0;
  assert.equal(scoreMessages(messages, scores).at(-1)?.relationship_index, Number((50 + 75 * Math.exp(-1)).toFixed(4)));
  assert.throws(() => scoreMessages(messages, scores.slice(1)), /数量/);
  assert.throws(() => scoreMessages(messages, scores.map(s => ({ ...s, id: 1 }))), /重复/);
  assert.throws(() => scoreMessages(messages, scores.map(s => ({ ...s, delta_vs_prior: NaN }))), /有效/);
  assert.throws(() => scoreMessages(messages, scores.map(s => ({ ...s, delta_vs_prior: 100 }))), /范围/);
});

test('imported scores require consistent non-negative safe integer IDs and preserve zero', () => {
  const message = { id: 0, timestamp: '2026-11-18T09:00:00+08:00', sender: 'A', message: '' };
  const score = { id: 0, delta_vs_prior: 1, delta_vs_atmosphere: 1, primary_dim: 'engagement', rationale: '' };
  const row = { ...message, ...score };
  assert.equal(loadScored([row])[0].id, 0);
  assert.equal(scoreMessages([message], [score])[0].id, 0);
  assert.equal(loadScored([{ ...row, i: 0 }])[0].id, 0);
  for (const id of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1, NaN, Infinity, -Infinity]) {
    assert.throws(() => loadScored([{ ...row, id }]), /ID 无效/);
    assert.throws(() => scoreMessages([{ ...message, id }], [score]), /消息 ID/);
    assert.throws(() => scoreMessages([message], [{ ...score, id }]), /评分 ID/);
  }
  assert.throws(() => loadScored([{ ...row, i: 1 }]), /冲突/);
  assert.throws(() => loadScored([{ ...row, id: null, i: 0 }]), /冲突/);
  assert.throws(() => loadScored([{ ...row, id: null }]), /ID 无效/);
  assert.throws(() => loadScored([row, row]), /重复/);
  const { id: omittedId, ...withoutId } = row;
  assert.equal(loadScored([{ ...withoutId, i: 0 }])[0].id, 0);
  assert.deepEqual(loadScored([withoutId, withoutId]).map(r => r.id), [1, 2]);
});

test('scored imports reject missing or non-finite deltas and recompute untrusted indices', () => {
  const row = { id: 1, timestamp: '2026-11-18T09:00:00+08:00', sender: 'A', message: '', delta_vs_prior: 1, delta_vs_atmosphere: 1 };
  for (const field of ['delta_vs_prior', 'delta_vs_atmosphere']) {
    for (const value of [undefined, null, '0', NaN, Infinity, -Infinity]) {
      assert.throws(() => loadScored([{ ...row, [field]: value }]), /有效.*评分/);
    }
  }
  assert.equal(loadScored([{ ...row, relationship_index: 999999 }])[0].relationship_index, 51);
  assert.equal(loadScored([{ ...row, relationship_index: NaN }])[0].relationship_index, 51);
});

test('volume counts Unicode code points and global reply gaps across candle boundaries', () => {
  const rows = scoreMessages(
    [{ id: 1, timestamp: '2026-11-18T00:59:50+08:00', sender: 'A', message: '🙂' },
      { id: 2, timestamp: '2026-11-18T01:00:10+08:00', sender: 'B', message: 'OK' }],
    [1, 2].map(id => ({ id, delta_vs_prior: 0, delta_vs_atmosphere: 0, primary_dim: 'engagement', rationale: '' })),
  );
  const candles = aggregate(rows, '1h');
  assert.deepEqual(candles.map(c => c.volume), [1.05, 2.6]);
  assert.equal(candles[0].time, Date.parse('2026-11-18T00:00:00+08:00') / 1000);
});

test('technical indicators omit warm-up bars and handle flat series without invalid points', () => {
  const candles = Array.from({ length: 60 }, (_, i) => ({ time: i * 86400, open: 50, high: 50, low: 50, close: 50, volume: 1, message_count: 1, events: [] }));
  assert.equal(lineIndicator(candles, 'ma')[0].data.length, 56);
  assert.equal(lineIndicator(candles, 'rsi')[0].data.length, 46);
  assert.equal(lineIndicator(candles, 'macd')[1].data.length, 27);
  for (const kind of ['ma', 'ema', 'bb', 'rsi', 'macd', 'kdj'] as IndicatorKind[]) {
    const expected = kind === 'rsi' ? 100 : kind === 'macd' ? 0 : 50;
    for (const line of lineIndicator(candles, kind)) assert.ok(line.data.every(point => point.value === expected));
  }
  assert.equal(lineIndicator(candles.slice(0, 3), 'bb')[0].data.length, 0);
});
